create table if not exists cz_remediations(id uuid primary key default gen_random_uuid(),company_id uuid not null,revision_id uuid not null,failure_signature text not null,state text not null,data jsonb not null default '{}',created_at timestamptz not null default now());
create unique index if not exists cz_one_active_remediation on cz_remediations(company_id,revision_id,failure_signature) where state in('diagnosing','generating_candidates','experiment_queued','experiment_running','awaiting_decision');
create or replace function cz_begin_remediation(p_company uuid,p_revision uuid,p_signature text,p_data jsonb)returns jsonb language plpgsql security definer as $$declare r cz_remediations;made boolean:=false;begin insert into cz_remediations(company_id,revision_id,failure_signature,state,data)values(p_company,p_revision,p_signature,'diagnosing',p_data)on conflict(company_id,revision_id,failure_signature)where state in('diagnosing','generating_candidates','experiment_queued','experiment_running','awaiting_decision')do nothing returning * into r;if r.id is not null then made:=true;else select * into r from cz_remediations where company_id=p_company and revision_id=p_revision and failure_signature=p_signature and state in('diagnosing','generating_candidates','experiment_queued','experiment_running','awaiting_decision')order by created_at limit 1;end if;return to_jsonb(r)||jsonb_build_object('created',made);end$$;
alter table cz_queue add column if not exists work_key text;
create unique index if not exists cz_unique_experiment_work on cz_queue(company_id,work_key) where work_key is not null;
create unique index if not exists cz_unique_session_stage on cz_records(company_id,(data->>'sessionId'),(data->>'stage')) where kind='session_artifact';
create index if not exists cz_world_fact_session on cz_records(company_id,(data->>'sessionId'),created_at) where kind='world_fact';
create index if not exists cz_outcome_observation_session on cz_records(company_id,(data->>'sessionId'),(data->>'missionVersion'),created_at) where kind='outcome_observation';
create unique index if not exists cz_outcome_contract_mission_version on cz_records(company_id,(data->>'missionId'),(data->>'missionVersion')) where kind='outcome_contract';
create index if not exists cz_operation_plan_session on cz_records(company_id,(data->>'sessionId'),created_at) where kind='operation_plan';
create or replace function cz_enqueue(p_company_id uuid,p_job_id uuid,p_idempotency_key text default null)returns cz_queue language plpgsql security definer as $$declare result cz_queue;begin insert into cz_queue(company_id,job_id,idempotency_key,work_key)values(p_company_id,p_job_id,p_idempotency_key,p_idempotency_key)on conflict(company_id,idempotency_key)where idempotency_key is not null do update set updated_at=cz_queue.updated_at returning * into result;return result;end$$;
create or replace function cz_ensure_experiment_work(p_company uuid,p_work_key text,p_job jsonb)returns jsonb language plpgsql security definer as $$declare q cz_queue;j cz_records;jid uuid;begin if p_work_key is null or p_work_key=''then raise exception'work_key_required';end if;perform pg_advisory_xact_lock(hashtextextended(p_company::text||':'||p_work_key,0));select * into q from cz_queue where company_id=p_company and work_key=p_work_key;if q.id is not null then select * into j from cz_records where id=q.job_id;return jsonb_build_object('job',to_jsonb(j),'queue',to_jsonb(q),'created',false);end if;jid=(p_job->>'id')::uuid;insert into cz_records(id,company_id,kind,state,version,data,created_at,updated_at)values(jid,p_company,'job','queued',1,p_job->'data',coalesce((p_job->>'created_at')::timestamptz,now()),now())on conflict(id)do nothing;select * into j from cz_records where id=jid and company_id=p_company and kind='job';if j.id is null then raise exception'work_job_identity_conflict';end if;insert into cz_queue(company_id,job_id,idempotency_key,work_key)values(p_company,jid,p_work_key,p_work_key)returning * into q;return jsonb_build_object('job',to_jsonb(j),'queue',to_jsonb(q),'created',true);end$$;
alter table cz_budget_ledger add column if not exists state text not null default 'consumed' check(state in('reserved','consumed','released'));
alter table cz_budget_ledger add column if not exists expires_at timestamptz;
alter table cz_approvals add column if not exists invocation_key text;
create unique index if not exists cz_unique_approval_invocation on cz_approvals(company_id,invocation_key) where invocation_key is not null;
create table if not exists cz_invocations(id uuid primary key default gen_random_uuid(),company_id uuid not null,job_id uuid not null,run_id uuid not null,capability_id uuid not null,invocation_key text not null,state text not null check(state in('planned','approved','dispatched','confirmed','failed','uncertain')),input jsonb,output jsonb,error jsonb,dispatched_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,invocation_key));
create or replace function cz_reserve_budget(p_company_id uuid,p_source_ref text,p_amount numeric,p_limit numeric) returns uuid language plpgsql security definer as $$declare v uuid;s numeric;prior cz_budget_ledger;begin perform pg_advisory_xact_lock(hashtextextended(p_company_id::text,0));select * into prior from cz_budget_ledger where source_ref=p_source_ref for update;if prior.id is not null and prior.state in('reserved','consumed')and(prior.state='consumed'or prior.expires_at>now())then return prior.id;end if;select coalesce(sum(amount_usd),0)into s from cz_budget_ledger where company_id=p_company_id and created_at>=date_trunc('day',now())and(state='consumed'or(state='reserved'and expires_at>now()));if s+p_amount>p_limit then raise exception 'budget_exceeded';end if;if prior.id is not null then update cz_budget_ledger set state='reserved',amount_usd=p_amount,expires_at=now()+interval '5 minutes' where id=prior.id returning id into v;else insert into cz_budget_ledger(company_id,amount_usd,category,source_ref,state,expires_at)values(p_company_id,p_amount,'capability',p_source_ref,'reserved',now()+interval '5 minutes')returning id into v;end if;return v;end$$;
create or replace function cz_settle_budget(p_id uuid,p_state text)returns void language plpgsql security definer as $$declare current_state text;begin if p_state not in('consumed','released')then raise exception 'invalid_budget_state';end if;select state into current_state from cz_budget_ledger where id=p_id for update;if current_state is null then raise exception 'reservation_not_found';end if;if current_state=p_state then return;end if;if current_state<>'reserved'then raise exception'reservation_already_settled';end if;update cz_budget_ledger set state=p_state,expires_at=null where id=p_id;end$$;
create or replace function cz_promote_candidate(p_company uuid,p_experiment uuid,p_candidate uuid)returns jsonb language plpgsql security definer as $$declare c cz_records;e cz_records;n cz_records;r jsonb;d uuid:=gen_random_uuid();l uuid:=gen_random_uuid();begin select * into c from cz_records where id=p_company and kind='company' for update;select * into e from cz_records where id=p_experiment and company_id=p_company and kind='experiment' for update;if e.state<>'awaiting_decision'then raise exception'experiment_not_ready';end if;if c.data->>'activeOrganizationRevisionId'<>e.data->>'baselineRevisionId'then raise exception'stale_experiment_baseline';end if;select value into r from jsonb_array_elements(e.data->'results')value where value->>'candidateRevisionId'=p_candidate::text;if r is null or not(e.data->'candidateRevisionIds'?p_candidate::text)or not coalesce((r->>'constitutionPassed')::boolean,false)or coalesce(r->>'policyStatus','FAIL')<>'PASS'or coalesce((r->>'uncertainCases')::integer,0)>0 or coalesce((r->>'cases')::numeric,0)<coalesce((r->>'minCases')::numeric,1)or coalesce((r->>'qualityDelta')::numeric,0)<=0 or coalesce((r->>'costDelta')::numeric,0)>0 then raise exception'promotion_gate_failed';end if;select * into n from cz_records where id=p_candidate and company_id=p_company and kind='candidate_revision'for update;if n.id is null then raise exception'candidate_not_found';end if;update cz_records set state='retired',data=jsonb_set(data,'{status}','"retired"')where id=(e.data->>'baselineRevisionId')::uuid;update cz_records set kind='organization_revision',state='production',data=jsonb_set(data,'{status}','"production"')where id=p_candidate;update cz_records set data=jsonb_set(data,'{activeOrganizationRevisionId}',to_jsonb(p_candidate::text)),version=version+1 where id=p_company;update cz_records set state='promoted'where id=p_experiment;insert into cz_records(id,company_id,kind,state,data)values(d,p_company,'promotion_decision','promoted',jsonb_build_object('experimentId',p_experiment,'candidateRevisionId',p_candidate,'inputs',r));insert into cz_records(id,company_id,kind,state,data)values(l,p_company,'lesson','active',jsonb_build_object('experimentId',p_experiment,'remediationId',e.data->'remediationId','datasetId',e.data->'datasetId','candidateRevisionId',p_candidate,'mutation',n.data->'mutation','outcome',r,'evidenceIds',coalesce(e.data->'sourceJobIds','[]'::jsonb),'decision','promote'));insert into cz_audit_events(company_id,actor,action,subject_kind,subject_id,data)values(p_company,'promotion_rpc','organization.promoted','organization_revision',p_candidate,jsonb_build_object('experimentId',p_experiment));return jsonb_build_object('decisionId',d,'lessonId',l);end$$;
create or replace function cz_rollback_revision(p_company uuid,p_target uuid)returns jsonb language plpgsql security definer as $$declare c cz_records;t cz_records;cur cz_records;restored uuid:=gen_random_uuid();next_revision integer;begin select * into c from cz_records where id=p_company and kind='company' for update;if c.id is null then raise exception'company_not_found';end if;select * into t from cz_records where id=p_target and company_id=p_company and kind in('organization_revision','candidate_revision');if t.id is null then raise exception'target_revision_not_found';end if;select * into cur from cz_records where id=(c.data->>'activeOrganizationRevisionId')::uuid and company_id=p_company and kind='organization_revision' for update;if cur.id is null then raise exception'active_revision_not_found';end if;select coalesce(max((data->>'revision')::integer),0)+1 into next_revision from cz_records where company_id=p_company and kind in('organization_revision','candidate_revision');insert into cz_records(id,company_id,kind,state,data)values(restored,p_company,'organization_revision','production',jsonb_set(jsonb_set(jsonb_set(jsonb_set(t.data,'{revision}',to_jsonb(next_revision)),'{parentRevisionId}',to_jsonb(cur.id::text)),'{status}','"production"'),'{rollbackOfRevisionId}',to_jsonb(t.id::text)));update cz_records set state='retired',data=jsonb_set(data,'{status}','"retired"'),version=version+1 where id=cur.id;update cz_records set data=jsonb_set(data,'{activeOrganizationRevisionId}',to_jsonb(restored::text)),version=version+1 where id=p_company;insert into cz_audit_events(company_id,actor,action,subject_kind,subject_id,data)values(p_company,'rollback_rpc','organization.rollback','organization_revision',restored,jsonb_build_object('fromRevisionId',cur.id,'targetRevisionId',t.id));return jsonb_build_object('id',restored,'company_id',p_company,'kind','organization_revision','state','production','version',1,'data',(select data from cz_records where id=restored));end$$;
